SPEC.D4=function(p){
  var s=[bg(C.sage)].concat(chrome(p),[
    T('Discovery outcomes, quantified',{x:7.5,y:11.5,w:60,h:7,s:4.2,b:true,tight:true}),
    CH({type:'doughnut',x:6,y:22,w:24,h:24,
      data:[{name:'Validated',labels:['Validated','Open'],values:[68,32]}],
      opts:{holeSize:62,chartColors:[C.g900,C.g200],dataLabelFormatCode:' '}}),
    T('68%',{x:11.6,y:31.5,w:13,h:5,s:3.4,b:true,al:'center',tight:true}),
    T('validated',{x:11.6,y:36,w:13,h:2.4,s:1.15,b:true,al:'center',c:C.g600}),
    T('Of 25 hypotheses raised in a 6-week paid discovery, two thirds survived contact with real operations.',
      {x:34,y:21,w:38,h:8,s:1.75,c:C.g800,lh:1.45})]);
  var d=[['Hypotheses validated in the field','68%',68,0],['Flows reworked after grower testing','44%',44,0],['Scope removed before build','31%',31,1]];
  d.forEach(function(r,i){var y=30+i*6.4,w=52;
    s.push(T(r[0],{x:34,y:y,w:38,h:2.4,s:1.35,b:true}));
    s.push(T(r[1],{x:74,y:y,w:18,h:2.4,s:1.35,b:true,c:C.g600,al:'right'}));
    s.push(R({x:34,y:y+3,w:w+6,h:1,fill:C.g200,radius:.5}));
    s.push(R({x:34,y:y+3,w:(w+6)*r[2]/100,h:1,fill:r[3]?C.lime:C.g900,radius:.5}));});
  return s;};

